arguments.command:
cat > /workspace/tmp/dev/gen_log.py <<'PYEOF'
import json, os, random, sys
sys.path.insert(0, '/workspace/tmp/dev')
plan = json.load(open('/workspace/tmp/dev/t/max_plan.json'))
probes = plan['probes']
rng = random.Random(99)
path = '/workspace/tmp/dev/t/max_log.jsonl'
n = 300000
with open(path, 'w') as f:
    for i in range(n):
        r = rng.random()
        if r < 0.55:
            p = probes[rng.randrange(len(probes))]
            recv = p['sent_ms'] + rng.randrange(p['deadline_ms'] - p['sent_ms'])
            if rng.random() < 0.5:
                src = p['target']
                t, c = 129, 0
            else:
                src = '2001:db8:ffff::%x' % rng.randrange(1, 5000)
                t, c = 1, rng.randrange(0, 7)
            row = {"probe_id": p['id'], "received_ms": recv, "target": p['target'],
                   "source": src, "type": t, "code": c}
            if rng.random() < 0.2:   # textual variant
                row['target'] = p['target'].upper().replace('::', ':0:0:0:0:0:0:0:')
                row['source'] = src.upper()
        elif r < 0.7:
            p = probes[rng.randrange(len(probes))]
            row = {"probe_id": p['id'], "received_ms": p['sent_ms'] - 5, "target": p['target'],
                   "source": p['target'], "type": 129, "code": 0}
        elif r < 0.8:
            row = {"probe_id": "nope/%d/0/low-1/0" % i, "received_ms": 5, "target": "2001:db8::1",
                   "source": "2001:db8::1", "type": 129, "code": 0}
        elif r < 0.9:
            row = {"probe_id": probes[0]['id'], "received_ms": 5, "target": "2001:db8::bad",
                   "source": "2001:db8::1", "type": 129, "code": 0}
        else:
            row = {"probe_id": probes[0]['id'], "received_ms": 5, "target": "2001:db8::1",
                   "source": "2001:db8::1", "type": 3, "code": 0}
        f.write(json.dumps(row) + '\n')
print('log bytes', os.path.getsize(path))
PYEOF
cd /workspace/tmp/dev && python3 gen_log.py && ls -la t/max_log.jsonl && /usr/bin/time -v python3 /workspace/submission/ipv6_replay.py replay t/max_manifest.json t/max_log.jsonl > t/max_replay.json 2> t/time.txt; echo "exit=$?"; grep -E "Elapsed|Maximum resident|User time|System time" t/time.txt; ls -la t/max_replay.json
